<?php
require __DIR__.'/config.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Habka codsiga lama oggola.');}verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$sql='SELECT pdf_filename FROM documents WHERE id=?';$args=[$id];if(($_SESSION['role']??'staff')!=='admin'){$sql.=' AND uploaded_by=?';$args[]=(int)$_SESSION['user_id'];}$stmt=$pdo->prepare($sql);$stmt->execute($args);$doc=$stmt->fetch();if(!$doc){header('Location: documents.php?deleted=0');exit;}$del=$pdo->prepare('DELETE FROM documents WHERE id=?');$del->execute([$id]);if($del->rowCount()&&is_file(__DIR__.'/uploads/'.$doc['pdf_filename']))@unlink(__DIR__.'/uploads/'.$doc['pdf_filename']);header('Location: documents.php?deleted=1');exit;
